import{_ as a,o as t,c as i,a3 as n}from"./chunks/framework.B5WAEDB7.js";const u=JSON.parse('{"title":"List","description":"Display entries compactly, stacked one below the other, and sort them manually.","frontmatter":{"title":"List","description":"Display entries compactly, stacked one below the other, and sort them manually."},"headers":[],"relativePath":"en/ansichten/liste.md","filePath":"en/ansichten/liste.md","lastUpdated":1787319236000}'),r={name:"en/ansichten/liste.md"};function s(o,e,l,d,h,c){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="list" tabindex="-1">List <a class="header-anchor" href="#list" aria-label="Permalink to &quot;List&quot;">​</a></h1><p>The <strong>List</strong> displays entries compactly, stacked one below the other — more space-efficient than the table and easier to read on narrow screens.</p><p><strong>Suited for:</strong> task lists, checklists, priority lists, mobile use, embedded overviews in <a href="/en/seiten/portal-veroeffentlichen">portals</a>.</p><h2 id="create-a-list" tabindex="-1">Create a list <a class="header-anchor" href="#create-a-list" aria-label="Permalink to &quot;Create a list&quot;">​</a></h2><ol><li>Under the Grid, choose <strong>Create view</strong>.</li><li>Choose <strong>List</strong>.</li></ol><p>The list needs <strong>no special column</strong> and works right away.</p><h2 id="manual-order-via-drag-and-drop" tabindex="-1">Manual order via drag and drop <a class="header-anchor" href="#manual-order-via-drag-and-drop" aria-label="Permalink to &quot;Manual order via drag and drop&quot;">​</a></h2><p>The most important difference from the table: entries can be put in order <strong>by hand</strong>, by dragging them.</p><div class="warning custom-block"><p class="custom-block-title">Sorting disables drag and drop</p><blockquote><p><em>Drag and drop is disabled while sorting is active.</em></p></blockquote><p>Once a sort is active, it determines the order — manual arrangement would otherwise have no effect.</p><p><strong>If you want to sort manually, remove the view&#39;s sort first.</strong></p></div><div class="tip custom-block"><p class="custom-block-title">Manual order or sorting — pick one</p><p>You can&#39;t have both at once. Consider what fits your case:</p><ul><li><strong>Manual order</strong> for priorities, workflows, and anything where the order is a deliberate decision.</li><li><strong>Sorting</strong> for anything derived from the data — due date, amount, name.</li></ul><p>If you need both, create two views: a sorted one for analysis and a manual one for prioritizing.</p></div><h2 id="which-fields-appear" tabindex="-1">Which fields appear <a class="header-anchor" href="#which-fields-appear" aria-label="Permalink to &quot;Which fields appear&quot;">​</a></h2><p>As in any view, via the visible columns. Since the list is compact, hiding columns pays off especially here.</p><p>→ <a href="/en/ansichten/spalten-verwalten">Manage columns</a></p><h2 id="filter-and-grouping" tabindex="-1">Filter and grouping <a class="header-anchor" href="#filter-and-grouping" aria-label="Permalink to &quot;Filter and grouping&quot;">​</a></h2><p>Work as in any view.</p><div class="tip custom-block"><p class="custom-block-title">A grouped list as an overview</p><p>A list grouped by a status field makes a compact alternative to the <a href="/en/ansichten/kanban">Kanban board</a> — especially on narrow screens, where side-by-side columns aren&#39;t practical.</p></div><p>→ <a href="/en/ansichten/filtern-sortieren-gruppieren">Filtering, Sorting, Grouping</a></p><h2 id="embedding-a-list-in-a-page" tabindex="-1">Embedding a list in a page <a class="header-anchor" href="#embedding-a-list-in-a-page" aria-label="Permalink to &quot;Embedding a list in a page&quot;">​</a></h2><p>The List works well for <a href="/en/seiten/was-sind-seiten">pages and portals</a>: use the <strong>Grid View</strong> block to embed it, and the block settings control whether visitors can search, filter, and open entries.</p><p>For freely designed lists, there&#39;s also the <strong>Grid List</strong> block, where you build the look of each list entry yourself.</p><p>→ <a href="/en/seiten/auswertungen">Embedding views and reports</a></p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/ansichten/was-ist-eine-ansicht">What is a View</a></li><li><a href="/en/ansichten/kanban">Kanban</a></li><li><a href="/en/ansichten/spalten-verwalten">Manage columns</a></li></ul>',23)])])}const g=a(r,[["render",s]]);export{u as __pageData,g as default};
